E1.css:
[data-ui-unit="E1"] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 54px;
  padding-top: 8px;
  padding-bottom: 8px;
  width: 100%;
}

[data-ui-unit="E1"] .e1-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--ink);
  margin: 0;
  line-height: 1.2;
}

[data-ui-unit="E1"] .e1-tools {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-shrink: 0;
}

[data-ui-unit="E1"] button {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

[data-ui-unit="E1"] img {
  display: block;
  width: 24px;
  height: 24px;
  color: var(--muted);
  filter: saturate(0) opacity(0.6);
}

@media (max-width: 320px) {
  [data-ui-unit="E1"] .e1-title {
    font-size: 16px;
  }
}

@media (min-width: 431px) {
  [data-ui-unit="E1"] {
    padding-left: 0;
    padding-right: 0;
  }
}
